import (
	"testing"
	"time"
)

// A zone west of UTC makes the UTC-truncated day one calendar day early,
// so Next could return a time before its argument.
func TestWeeklyNextNotBeforeAfterWestOfUTC(t *testing.T) {
	r, err := Parse("on sun at 09:30", LookupZone("America/New_York"), start)
	if err != nil {
		t.Fatal(err)
	}
	// Sunday 2026-10-11 10:00 EDT, after the 09:30 slot has passed.
	after := time.Date(2026, 10, 11, 14, 0, 0, 0, time.UTC)
	want := time.Date(2026, 10, 18, 13, 30, 0, 0, time.UTC) // Sunday 09:30 EDT
	if got := r.Next(after); !got.Equal(want) {
		t.Errorf("Next(%v) = %v, want %v", after, got, want)
	}
}
"}

